<template>
	<view class="container">
		<u-loading-page :loading="true" v-if="load" fontSize="28rpx" />
		<block v-else>
			<view class="goods-info">
				<view class="banner">
					<u-swiper :list="goods_imgs"
					interval="5000" 
					circular 
					indicator
					indicatorMode="dot"
					height="400"
					:autoplay="false" 
					indicatorActiveColor="#EC5662"
					indicatorInactiveColor="rgba(236, 86, 98, 0.3)"
					radius="0"
					keyName="image_url"/>
					<view class="goods-title">
						<view class="goods-price">
							<view class="left">
								<text>¥</text>
								<text class="jiage">{{detail.goods_price}}</text>
							</view>
							<view class="right" v-if="false">
								<image src="@/static/common/weixin.png" mode="widthFix" class="wx-img" />
								<text>分享</text>
							</view>
						</view>
						<view class="goods-name">{{detail.goods_name}}</view>
						<view class="goods-jifen">
							<text>{{detail.jifen}}积分+{{detail.cash}}金豆</text>
						</view>
					</view>
				</view>
				<view class="number-box">
					<view class="left">购买数量</view>
					<view class="right">
						<text :class="{'dis':goods_num<=1}" @click="changeNum(-1)">-</text>
						<text class="number">{{goods_num}}</text>
						<text :class="{'dis':goods_num>=detail.store_count}" @click="changeNum(1)">+</text>
					</view>
				</view>
				<view class="detail">
					<view class="title">
						<text class="line"></text>
						<text class="text">商品信息</text>
						<text class="line"></text>
					</view>
					<view class="detail-info" v-html="detail.goods_content">
						<web-view :src="goods_web_url" v-if="false"></web-view>
					</view>
				</view>
				<view style="height: 135rpx;"></view>
			</view>
			<view class="bottom">
				<view class="left">
					<view class="left-item" @click="goIndex">
						<image src="@/static/index/shouye.png" class="left-item-img" mode="widthFix"/>
						<view>首页</view>
					</view>
				</view>
				<view class="right">
					<button class="buy-now" @click="buy_now()">立即购买</button>
				</view>
			</view>
		</block>
	</view>
</template>

<script>
	var _this;
	function sortNumber(a,b)
	{
		return a - b
	}
	export default {
		data() {
			return {
				goods_id: 0,
				goods_num:1,
				goods_imgs:[]
			};
		},
		methods: {
			//立即购买
			buy_now(){
				var url = `/pages/cart/jf-submit?goods_id=${_this.goods_id}&goods_num=${_this.goods_num}`;
				_this.toNext(url)
			},
			changeNum(step){
				var max=_this.detail.store_count;
				var number=parseInt(_this.goods_num)+step
				if (step<0){
					if(number<1){
						return
					}
					_this.goods_num=number
				}else {
					if (number>max){
						return;
					}
					_this.goods_num=number
				}
			},
			async get_shangpin_xq() {
				const params = {
					goods_id: _this.goods_id,
				}
				const data = await _this.$post('port/jf_goods_xq', params)
				if (data.code == 200) {
					_this.detail = data.result.goods
					_this.goods_imgs = data.result.goods_imgs
				} else {
					this.$u.toast(data.msg)
				}
				if (_this.load) {
					_this.load = false
				}
			},
			//跳转到购物车界面
			goCart(){
				uni.switchTab({
					url:'/pages/cart/cart'
				})
			}
		},
		onLoad(e) {
			_this = this;
			if (e.goods_id) {
				_this.goods_id = e.goods_id
			} else {
				this.$u.toast('提交参数有误')
				setTimeout(() => {
					uni.navigateBack()
				}, 2000)
				return;
			}
			_this.get_shangpin_xq()
		},
		onReady() {
			
		},
		computed: {}
	}
</script>

